"""Booking records."""


class Booking:
    def __init__(self, hotel, nights):
        self.hotel = hotel
        self.nights = nights

    def __repr__(self):
        return "Booking(%r, %r)" % (self.hotel, self.nights)


ROWS = [('plaza', 50), ('grand', 37), ('plaza', 19), ('plaza', 23), ('plaza', 22), ('grand', 58)]


def load_bookings():
    """Yield the stored bookings one at a time."""
    for hotel, nights in ROWS:
        yield Booking(hotel, nights)


def feed_bookings():
    """Endless feed of bookings: repeats the stored rows for ever."""
    while True:
        for hotel, nights in ROWS:
            yield Booking(hotel, nights)
